HIGHLIGHTS = {
'S01':['2024年9月26日','宣判'],'S02':['五十八年','无罪'],'S03':['1966年6月30日','起火'],'S04':['警灯','浓烟'],'S05':['一家四口','展开勘查'],'S06':['现金失踪','强盗杀人案'],'S07':['袴田岩','三十岁'],'S08':['前拳击手','警方离开'],'S09':['连续数周','十多个小时'],'S10':['口供','否认杀人'],'S11':['一年多后','味噌桶'],'S12':['五件旧衣物','关键证据'],'S13':['1968年','没有杀人'],'S14':['死刑','1980年'],'S15':['东京拘置所','漫长岁月'],'S16':['执行当天早晨','等待'],'S17':['数十年','白发'],'S18':['每个清晨','等待'],'S19':['姐姐秀子','不相信'],'S20':['发传单','鞠躬'],'S21':['1981年','驳回'],'S22':['2014年3月','获释'],'S23':['提出抗告','再审'],'S24':['味噌','观察颜色'],'S25':['2023年3月','决定重审'],'S26':['2024年9月26日','静冈地方法院'],'S27':['无罪','姐姐流泪'],'S28':['侦查机关捏造','衣物碎片'],'S29':['终于画上句号','黄昏暖光'],'S30':['五十八年','怎样对待']}


def build() -> dict:
    refs = json.loads((HERE / "reference" / "approvals.json").read_text(encoding="utf-8"))["assets"]
    ref_ids = list(refs)
    shots = []
    for index, row in enumerate(ROWS):
        sid, ref_text, role_text, narration, camera, sfx, visual = row
        ref_list = ref_text.split(",")
        characters = [] if role_text == "—" else role_text.split(";")
        anchors = "；".join(CHARACTERS[c] for c in characters)
        ref_notes = "【参考图说明】" + "；".join(
            f"图{n}为{rid}（{refs[rid]['description']}），仅作人物身份、服装、场景结构或道具外观参考；不要复制设定板/拼贴排版。"
            for n, rid in enumerate(ref_list, 1))
        prompt = "\n".join([STYLE, anchors, visual + " 运镜：" + camera, ref_notes, NEGATIVE])
        shots.append({"id":sid,"start":index*6,"duration":6,"kind":"agnes",
                      "reference_images":ref_list,"character_anchors":characters,
                      "narration":narration,"narration_id":sid,"camera":camera,"sfx":sfx,
                      "visual_prompt":visual,"prompt":prompt,"subtitle":narration,
                      "highlight_keywords":HIGHLIGHTS[sid],"seed":58000+index})
    reference_images = [{"id":rid,"file":refs[rid]["file"],"kind":"character" if rid.startswith("C") else "scene" if rid.startswith("S") else "prop","description":refs[rid]["description"]} for rid in ref_ids]
    story = {"title":"他等了58年，才等来一个无罪：袴田事件","slug":"hakamada58",
             "target_duration":180,"aspect":"16:9","resolution":[1920,1080],"fps":24,
             "model":"agnes-video-2.5-flash","source_size":"720P","voice":"voice-00",
             "voice_style":"悬疑低沉、成熟男声，克制不煽情","style":STYLE,"negative":NEGATIVE,
             "shots":shots,"reference_images":reference_images,
             "reference_status":{"approved_generated":ref_ids,"pending":[]},
             "reference_mode_supported":True,"reference_support_status":"verified_from_sonofsam1977",
             "provider_constraints":"Verified against production/sonofsam1977: mode=reference, images=[1..5 public immutable raw URLs], Agnes 2.5 Flash, 30/30 successful receipts. Hakamada references are pinned to reference/revision.txt."}
    (HERE/"story.json").write_text(json.dumps(story,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    screenplay = ["# 《袴田事件：58年》分镜提示词包\n\n三分钟横屏 · 1920×1080 · 24fps · 30镜 · 180秒\n"]
    for shot in shots:
        screenplay.append(f"## {shot['id']}｜{shot['start']:03d}–{shot['start']+6:03d}s\n\n- 参考图：{', '.join(shot['reference_images'])}\n- 旁白：{shot['narration']}\n- 运镜：{shot['camera']}\n- 音效：{shot['sfx']}\n\n```text\n{shot['prompt']}\n```\n")
    (HERE/"screenplay.md").write_text("\n".join(screenplay),encoding="utf-8")
    print(f"Built {len(shots)} shots / 180s; {len(reference_images)} approved references.")
    return story

if __name__ == "__main__":
    build()
